
// Generated by IqwanEngine
// OWLFX Premium Responsive Navigation System

import React, { useEffect, useState } from "react";
import {
  Menu,
  X,
  Lock,
  GraduationCap,
  ChevronRight,
  Globe2,
} from "lucide-react";
import {
  Link,
  useLocation,
} from "react-router-dom";
import {
  AnimatePresence,
  motion,
  useReducedMotion,
} from "framer-motion";

import { useLanguage } from "../context/LanguageContext";

interface NavbarProps {
  onOpenAdmin: () => void;
}

interface MovingNavbarButtonProps {
  id?: string;
  onClick?: () => void;
  href?: string;
  label: string;
  className?: string;
}

const navMotion = {
  hidden: { opacity: 0, y: -8 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.25, ease: "easeOut" as const },
  },
  exit: {
    opacity: 0,
    y: -8,
    transition: { duration: 0.18 },
  },
};

// ------------------------------------------------------
// PREMIUM ANIMATED CTA
// ------------------------------------------------------

function MovingNavbarButton({
  id,
  onClick,
  href,
  label,
  className = "",
}: MovingNavbarButtonProps) {
  const reducedMotion = useReducedMotion() ?? false;

  const buttonContent = (
    <>
      {/* Market chart background */}
      <div
        aria-hidden="true"
        className="absolute inset-0 overflow-hidden rounded-full pointer-events-none"
      >
        <div className="absolute inset-0 flex items-end justify-between gap-[3px] px-4 opacity-30 group-hover:opacity-50 transition-opacity duration-300">
          {[35, 65, 45, 80, 55, 90, 40, 75, 50, 85, 60, 95].map(
            (height, index) => (
              <motion.span
                key={index}
                className="w-[2px] rounded-t-full shrink-0"
                style={{
                  backgroundColor:
                    index % 2 === 0 ? "#10B981" : "#EF4444",
                }}
                animate={
                  reducedMotion
                    ? { height: `${height * 0.55}%` }
                    : {
                        height: [
                          `${height * 0.25}%`,
                          `${height * 0.85}%`,
                          `${height * 0.4}%`,
                        ],
                      }
                }
                transition={
                  reducedMotion
                    ? { duration: 0 }
                    : {
                        duration: 1.5 + (index % 4) * 0.2,
                        repeat: Infinity,
                        repeatType: "reverse",
                        ease: "easeInOut",
                        delay: index * 0.04,
                      }
                }
              />
            ),
          )}
        </div>

        {!reducedMotion && (
          <svg
            className="absolute inset-0 w-full h-full opacity-50"
            viewBox="0 0 300 52"
            preserveAspectRatio="none"
          >
            <motion.path
              d="M0 32 Q25 8 50 25 T100 20 T150 35 T200 13 T250 27 T300 15"
              fill="none"
              stroke="white"
              strokeWidth="1.2"
              strokeDasharray="5 4"
              animate={{ x: [0, -25, 0] }}
              transition={{
                duration: 5,
                repeat: Infinity,
                ease: "linear",
              }}
            />
          </svg>
        )}

        <div className="absolute inset-0 bg-gradient-to-r from-amber-400/85 via-yellow-300/75 to-amber-500/85" />
      </div>

      {/* Shimmer */}
      {!reducedMotion && (
        <span
          aria-hidden="true"
          className="absolute inset-y-0 -left-1/2 w-1/3 skew-x-[-20deg] bg-gradient-to-r from-transparent via-white/45 to-transparent group-hover:left-[130%] transition-all duration-1000 ease-out"
        />
      )}

      <span className="relative z-10 flex items-center justify-center gap-2 text-[10px] sm:text-[11px] font-black uppercase tracking-[0.16em] text-[#17130A]">
        {label}
        <ChevronRight className="w-3.5 h-3.5 transition-transform group-hover:translate-x-1" />
      </span>
    </>
  );

  const baseClass = `
    group relative isolate inline-flex items-center justify-center
    min-h-[44px] overflow-hidden rounded-full
    border border-amber-200/70
    bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-500
    px-6 py-3
    shadow-[0_5px_25px_rgba(245,158,11,0.18)]
    hover:shadow-[0_7px_30px_rgba(245,158,11,0.35)]
    hover:-translate-y-0.5 active:translate-y-0
    transition-all duration-300
    focus-visible:outline-none focus-visible:ring-2
    focus-visible:ring-amber-300 focus-visible:ring-offset-2
    focus-visible:ring-offset-[#060911]
    ${className}
  `;

  if (href?.startsWith("/")) {
    return (
      <Link
        id={id}
        to={href}
        onClick={onClick}
        className={baseClass}
      >
        {buttonContent}
      </Link>
    );
  }

  if (href) {
    return (
      <a
        id={id}
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        onClick={onClick}
        className={baseClass}
      >
        {buttonContent}
      </a>
    );
  }

  return (
    <button
      id={id}
      type="button"
      onClick={onClick}
      className={baseClass}
    >
      {buttonContent}
    </button>
  );
}

// ------------------------------------------------------
// MAIN NAVBAR
// ------------------------------------------------------

export const Navbar: React.FC<NavbarProps> = ({ onOpenAdmin }) => {
  const { language, setLanguage, t } = useLanguage();
  const { pathname } = useLocation();

  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [imgError, setImgError] = useState(false);

  const reducedMotion = useReducedMotion() ?? false;

  // Navigation items
  const navLinks = [
    { name: t.nav.about, href: "/about-us" },
    { name: t.nav.groupSupport, href: "/group-support" },
    { name: t.nav.owlAlgo, href: "/owlalgo" },
    { name: t.nav.roadtour, href: "/roadtour" },
    { name: t.nav.ibDevelopment, href: "/ib-development" },
    { name: t.nav.education, href: "/education" },
    { name: t.nav.community, href: "/contact" },
  ];

  // Active route, including nested pages
  const isActiveRoute = (href: string) => {
    if (href === "/") return pathname === "/";
    return pathname === href || pathname.startsWith(`${href}/`);
  };

  // Scroll detection
  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 24);
    };

    handleScroll();

    window.addEventListener("scroll", handleScroll, {
      passive: true,
    });

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  // Lock body scroll while mobile drawer is open.
  // Restore the original overflow value instead of forcing "unset".
  useEffect(() => {
    const originalOverflow = document.body.style.overflow;

    if (mobileMenuOpen) {
      document.body.style.overflow = "hidden";
    }

    return () => {
      document.body.style.overflow = originalOverflow;
    };
  }, [mobileMenuOpen]);

  // Close drawer after route navigation
  useEffect(() => {
    setMobileMenuOpen(false);
  }, [pathname]);

  // Escape key closes mobile drawer
  useEffect(() => {
    if (!mobileMenuOpen) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setMobileMenuOpen(false);
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [mobileMenuOpen]);

  const toggleLanguage = () => {
    setLanguage(language === "MY" ? "EN" : "MY");
  };

  const closeMobileMenu = () => {
    setMobileMenuOpen(false);
  };

  const openAdminFromMobile = () => {
    setMobileMenuOpen(false);
    onOpenAdmin();
  };

  return (
    <header
      id="main-navbar-header"
      className={`
        fixed top-0 inset-x-0 z-50 isolate
        transition-all duration-300
        ${
          isScrolled
            ? "bg-[#060911]/95 backdrop-blur-2xl border-b border-amber-400/15 shadow-[0_12px_40px_rgba(0,0,0,0.45)]"
            : "bg-gradient-to-b from-[#060911]/85 to-transparent backdrop-blur-md"
        }
      `}
    >
      <div className="max-w-[1440px] mx-auto px-4 sm:px-6 xl:px-8">
        <div
          className={`
            flex items-center justify-between gap-4
            transition-all duration-300
            ${isScrolled ? "h-[68px]" : "h-[78px]"}
          `}
        >
          {/* --------------------------------
              BRAND LOGO
          --------------------------------- */}
          <Link
            id="brand-logo-link"
            to="/"
            onClick={closeMobileMenu}
            aria-label="OWLFX Home"
            className="group flex items-center gap-3 shrink-0 rounded-xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400"
          >
            <div className="relative w-10 h-10 sm:w-11 sm:h-11 shrink-0">
              <div className="absolute -inset-1 rounded-full bg-amber-400/10 blur-md opacity-0 group-hover:opacity-100 transition-opacity duration-300" />

              <div className="relative w-full h-full rounded-full border border-amber-400/25 bg-[#0B101A] flex items-center justify-center overflow-hidden shadow-[inset_0_0_15px_rgba(245,158,11,0.08)] group-hover:border-amber-400/60 transition-colors">
                {!imgError ? (
                  <picture className="block w-full h-full">
                    <source
                      srcSet="/OWLFXpng.webp"
                      type="image/webp"
                    />
                    <img
                      src="/OWLFXpng.png"
                      alt="OWLFX Official Logo"
                      width="48"
                      height="48"
                      fetchPriority="high"
                      loading="eager"
                      decoding="async"
                      onError={() => setImgError(true)}
                      className="w-full h-full object-contain p-0.5 group-hover:scale-105 transition-transform duration-300"
                    />
                  </picture>
                ) : (
                  <span className="text-amber-400 font-black text-xs tracking-tighter">
                    OWL
                  </span>
                )}
              </div>
            </div>

            <div className="flex flex-col min-w-0">
              <div className="flex items-center gap-2">
                <span className="text-[21px] sm:text-[23px] leading-none font-black tracking-tight text-white">
                  OWL<span className="text-amber-400">FX</span>
                </span>

                <span className="hidden sm:inline-flex items-center rounded-md border border-cyan-400/20 bg-cyan-400/[0.07] px-1.5 py-1 text-[8px] font-bold tracking-[0.15em] text-cyan-300">
                  {t.nav.badge}
                </span>
              </div>

              <span className="mt-1 text-[8px] sm:text-[9px] uppercase tracking-[0.22em] text-slate-400 font-semibold whitespace-nowrap">
                {t.nav.sub}
              </span>
            </div>
          </Link>

          {/* --------------------------------
              DESKTOP NAVIGATION
          --------------------------------- */}
          <nav
            id="desktop-nav-menu"
            aria-label="Main navigation"
            className="
              hidden xl:flex items-center
              gap-1 2xl:gap-1.5
              rounded-full
              border border-white/[0.07]
              bg-white/[0.035]
              backdrop-blur-xl
              p-1.5
              shadow-[inset_0_1px_0_rgba(255,255,255,0.035)]
            "
          >
            {navLinks.map((item) => {
              const active = isActiveRoute(item.href);
              const isEducation = item.href === "/education";

              return (
                <Link
                  key={item.href}
                  to={item.href}
                  aria-current={active ? "page" : undefined}
                  className={`
                    relative whitespace-nowrap
                    rounded-full px-3 2xl:px-3.5 py-2.5
                    text-[9px] 2xl:text-[10px]
                    font-bold uppercase tracking-[0.09em]
                    transition-all duration-200
                    focus-visible:outline-none focus-visible:ring-2
                    focus-visible:ring-amber-400
                    ${
                      active
                        ? isEducation
                          ? "bg-emerald-400/10 text-emerald-300"
                          : "bg-amber-400/10 text-amber-300"
                        : isEducation
                          ? "text-emerald-400/80 hover:bg-emerald-400/[0.07] hover:text-emerald-300"
                          : "text-slate-400 hover:bg-white/[0.06] hover:text-white"
                    }
                  `}
                >
                  {item.name}

                  {active && (
                    <motion.span
                      layoutId="owlfx-active-nav"
                      className={`
                        absolute bottom-0 left-1/2 -translate-x-1/2
                        w-5 h-[2px] rounded-full
                        ${
                          isEducation
                            ? "bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.7)]"
                            : "bg-amber-400 shadow-[0_0_8px_rgba(245,158,11,0.7)]"
                        }
                      `}
                      transition={
                        reducedMotion
                          ? { duration: 0 }
                          : { type: "spring", stiffness: 400, damping: 30 }
                      }
                    />
                  )}
                </Link>
              );
            })}
          </nav>

          {/* --------------------------------
              DESKTOP ACTIONS
          --------------------------------- */}
          <div className="hidden xl:flex items-center gap-2 shrink-0">
            {/* Language */}
            <div
              id="language-switcher"
              className="flex items-center gap-0.5 p-1 rounded-full border border-white/[0.07] bg-white/[0.035]"
              aria-label="Language selection"
            >
              {(["MY", "EN"] as const).map((lang) => (
                <button
                  key={lang}
                  id={`language-switch-${lang.toLowerCase()}`}
                  type="button"
                  onClick={() => setLanguage(lang)}
                  aria-pressed={language === lang}
                  title={lang === "MY" ? "Bahasa Melayu" : "English"}
                  className={`
                    min-w-[34px] h-8 rounded-full
                    text-[9px] font-black tracking-wider
                    transition-all duration-200
                    focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400
                    ${
                      language === lang
                        ? "bg-amber-400 text-[#17130A] shadow-[0_2px_12px_rgba(245,158,11,0.2)]"
                        : "text-slate-400 hover:text-white"
                    }
                  `}
                >
                  {lang}
                </button>
              ))}
            </div>

            {/* Admin */}
            <button
              id="navbar-admin-trigger"
              type="button"
              onClick={onOpenAdmin}
              aria-label={t.nav.adminCms}
              title="Admin CMS"
              className="
                w-10 h-10 flex items-center justify-center
                rounded-full border border-white/[0.08]
                bg-white/[0.035] text-slate-400
                hover:text-amber-300 hover:border-amber-400/30
                hover:bg-amber-400/[0.07]
                transition-all duration-200
                focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400
              "
            >
              <Lock className="w-4 h-4" />
            </button>
          </div>

          {/* --------------------------------
              TABLET / MOBILE CONTROLS
          --------------------------------- */}
          <div className="flex xl:hidden items-center gap-2 shrink-0">
            <button
              id="mobile-language-toggle"
              type="button"
              onClick={toggleLanguage}
              aria-label="Change language"
              className="
                min-w-[44px] h-10 px-3
                flex items-center justify-center gap-1.5
                rounded-full border border-white/10
                bg-white/[0.04] text-slate-200
                text-[10px] font-black tracking-wider
                hover:border-amber-400/30 hover:text-amber-300
                transition-colors
              "
            >
              <Globe2 className="w-3.5 h-3.5" />
              {language}
            </button>

            <button
              id="mobile-hamburger-btn"
              type="button"
              onClick={() => setMobileMenuOpen((open) => !open)}
              aria-label={mobileMenuOpen ? "Tutup menu" : "Buka menu"}
              aria-expanded={mobileMenuOpen}
              aria-controls="mobile-nav-drawer"
              className="
                relative w-11 h-11
                flex items-center justify-center
                rounded-full border border-white/10
                bg-white/[0.045] text-white
                hover:border-amber-400/40 hover:text-amber-300
                active:scale-95
                transition-all duration-200
                focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400
              "
            >
              <AnimatePresence mode="wait" initial={false}>
                <motion.span
                  key={mobileMenuOpen ? "close" : "open"}
                  initial={reducedMotion ? false : { opacity: 0, rotate: -45, scale: 0.7 }}
                  animate={{ opacity: 1, rotate: 0, scale: 1 }}
                  exit={reducedMotion ? undefined : { opacity: 0, rotate: 45, scale: 0.7 }}
                  transition={{ duration: reducedMotion ? 0 : 0.15 }}
                  className="absolute"
                >
                  {mobileMenuOpen ? (
                    <X className="w-5 h-5" />
                  ) : (
                    <Menu className="w-5 h-5" />
                  )}
                </motion.span>
              </AnimatePresence>
            </button>
          </div>
        </div>
      </div>

      {/* --------------------------------
          MOBILE BACKDROP
      --------------------------------- */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.button
            key="mobile-backdrop"
            type="button"
            aria-label="Tutup menu"
            tabIndex={-1}
            onClick={closeMobileMenu}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: reducedMotion ? 0 : 0.2 }}
            className="fixed inset-0 z-10 bg-black/65 backdrop-blur-[3px] xl:hidden"
          />
        )}
      </AnimatePresence>

      {/* --------------------------------
          MOBILE DRAWER
      --------------------------------- */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div
            id="mobile-nav-drawer"
            key="mobile-drawer"
            role="dialog"
            aria-modal="true"
            aria-label="Navigation menu"
            variants={navMotion}
            initial="hidden"
            animate="visible"
            exit="exit"
            transition={
              reducedMotion
                ? { duration: 0 }
                : undefined
            }
            className="
              absolute z-20 top-full left-3 right-3
              mt-2 xl:hidden
              max-h-[calc(100dvh-100px)]
              overflow-y-auto overscroll-contain
              rounded-[26px]
              border border-amber-400/15
              bg-[#080D17]/[0.98]
              shadow-[0_25px_80px_rgba(0,0,0,0.75)]
              backdrop-blur-2xl
            "
          >
            {/* Drawer heading */}
            <div className="flex items-center justify-between px-5 pt-5 pb-4 border-b border-white/[0.07]">
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-white">
                  OWL<span className="text-amber-400">FX</span>
                  <span className="ml-2 text-slate-500">MENU</span>
                </p>
                <p className="mt-1 text-[9px] text-slate-500 tracking-wider">
                  {t.nav.sub}
                </p>
              </div>

              <span className="flex items-center gap-1.5 text-[8px] font-mono uppercase tracking-widest text-emerald-400">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.8)]" />
                Navigation
              </span>
            </div>

            {/* Navigation links */}
            <div className="p-3 sm:p-4 space-y-1.5">
              {navLinks.map((item, index) => {
                const active = isActiveRoute(item.href);
                const isEducation = item.href === "/education";

                return (
                  <motion.div
                    key={item.href}
                    initial={reducedMotion ? false : { opacity: 0, x: -8 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{
                      duration: reducedMotion ? 0 : 0.2,
                      delay: reducedMotion ? 0 : index * 0.035,
                    }}
                  >
                    <Link
                      to={item.href}
                      onClick={closeMobileMenu}
                      aria-current={active ? "page" : undefined}
                      className={`
                        group flex items-center justify-between
                        min-h-[50px] px-4 py-3
                        rounded-2xl border
                        transition-all duration-200
                        active:scale-[0.985]
                        ${
                          active
                            ? isEducation
                              ? "bg-emerald-400/10 border-emerald-400/25 text-emerald-300"
                              : "bg-amber-400/[0.09] border-amber-400/25 text-amber-300"
                            : isEducation
                              ? "bg-emerald-400/[0.025] border-emerald-400/[0.08] text-emerald-300/80 hover:bg-emerald-400/[0.07]"
                              : "bg-white/[0.025] border-white/[0.045] text-slate-300 hover:bg-white/[0.06] hover:border-white/10 hover:text-white"
                        }
                      `}
                    >
                      <span className="flex items-center gap-3 min-w-0">
                        {isEducation && (
                          <GraduationCap className="w-[17px] h-[17px] shrink-0" />
                        )}

                        <span className="text-[10px] sm:text-[11px] font-bold uppercase tracking-[0.12em]">
                          {item.name}
                        </span>
                      </span>

                      <ChevronRight
                        className={`
                          w-4 h-4 shrink-0 transition-transform duration-200
                          group-hover:translate-x-1
                          ${
                            active
                              ? "text-amber-400"
                              : "text-slate-600 group-hover:text-slate-300"
                          }
                          ${isEducation ? "text-emerald-400" : ""}
                        `}
                      />
                    </Link>
                  </motion.div>
                );
              })}
            </div>

            {/* Drawer actions */}
            <div className="px-4 pb-5">
              <div className="border-t border-white/[0.07] pt-4 space-y-3">
                <p className="text-[9px] font-bold uppercase tracking-[0.18em] text-slate-500 px-1">
                  Quick Access
                </p>

                <MovingNavbarButton
                  id="mobile-cta-vip"
                  href="/interested?action=register"
                  label={t.nav.ctaVip}
                  className="w-full"
                  onClick={closeMobileMenu}
                />

                <button
                  id="mobile-admin-btn"
                  type="button"
                  onClick={openAdminFromMobile}
                  className="
                    w-full min-h-[46px]
                    flex items-center justify-center gap-2
                    rounded-full border border-white/[0.08]
                    bg-white/[0.035] text-slate-400
                    hover:text-amber-300 hover:border-amber-400/25
                    hover:bg-amber-400/[0.05]
                    text-[10px] font-bold uppercase tracking-[0.14em]
                    transition-all duration-200
                  "
                >
                  <Lock className="w-3.5 h-3.5" />
                  {t.nav.adminCms}
                </button>
              </div>

              <div className="mt-5 flex items-center justify-between text-[8px] text-slate-600 font-mono uppercase tracking-widest">
                <span>OWLFX • One World Legacy</span>
                <span>{language}</span>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
};
